import{_ as t,o as a,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"3.2.2 Sign In With Email","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-2-sign-in-with-email/spec.md","filePath":"feature/authentication/3-2-2-sign-in-with-email/spec.md"}'),n={name:"feature/authentication/3-2-2-sign-in-with-email/spec.md"};function s(r,e,l,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-2-2-sign-in-with-email" tabindex="-1">3.2.2 Sign In With Email <a class="header-anchor" href="#_3-2-2-sign-in-with-email" aria-label="Permalink to &quot;3.2.2 Sign In With Email&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.2</td></tr><tr><td>Feature</td><td>Sign In with Email/Phone + Password</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>GUEST holding an existing account</td></tr><tr><td>Routes</td><td><code>POST /api/v1/auth/login</code>, <code>POST /api/v1/auth/refresh</code></td></tr><tr><td>Related FRs</td><td>3.2.3 Google Sign-In, 3.2.4 Reset Password, 3.2.7 Two-Factor Verify, 3.2.8 Logout (separate FR, not covered here)</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a Guest with an existing account visits /login and submits an identifier, either an email address or a phone number, together with a password.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> GUEST holding an existing account.</li><li><strong>Purpose:</strong> Authenticate with an email address or phone number and a password, and obtain an access token plus a refresh token, without a further one-time code unless two-factor authentication is enabled.</li><li><strong>Interface:</strong> Sign-in form with an identifier input (email address or phone number), a Password input and a &quot;Forgot password&quot; link leading to Reset Password (3.2.4). The same screen also carries the Google sign-in entry point (3.2.3).</li><li><strong>Data Processing:</strong> The system resolves the identifier, checks the account status, compares the password against the stored hash, records the sign-in, resolves the active workspace and issues an access token together with a rotating refresh token; when two-factor authentication is enabled it issues a challenge token instead of the tokens.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Sign-in Screen (<code>LoginPage.tsx</code>, route <code>/login</code>):</p><ul><li>Split layout: brand panel on the left (<code>AuthBrandPanel</code>), form on the right, with a mobile header shown on small screens.</li><li>A &quot;Sign in / Sign up&quot; tab pair above the form; &quot;Sign up&quot; navigates to <code>/register</code>.</li><li>Identifier input labelled &quot;Email&quot; with placeholder <code>hello@company.com / 0912 345 678</code> (single field, accepts either email or phone), and a password input (<code>PasswordInput</code>, masked with reveal toggle) with a &quot;Forgot password&quot; link next to its label leading to <code>/forgot-password</code> (Reset Password, 3.2.4).</li><li>Submit button &quot;Sign in&quot; (loading state while the request is in flight).</li><li>Divider &quot;Or continue with&quot;, then a Google sign-in icon button linking to the OAuth entry point (3.2.3) via <code>oauthUrl(&quot;google&quot;)</code>.</li><li>Terms of Service / Privacy Policy notice below the form; a <code>DevQuickLogin</code> helper is shown (dev/test builds only).</li><li>On success: the client stores the access token, calls <code>GET /api/v1/users/me</code> to load the real profile, then navigates to the page the user was redirected from (or the Dashboard / Agency list) and shows toast MSG11.</li><li>When two-factor authentication is required: the client stores the <code>twoFactorToken</code> in <code>sessionStorage</code> and navigates to <code>/2fa-verify</code> (3.2.7) without storing any access token.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> identifier (email address or phone number), password.</li><li><strong>Input optional:</strong> none.</li><li><strong>System data:</strong> userId, role, status, twoFactorEnabled, lastLoginAt, workspaceId, accessToken, refreshToken.</li><li><strong>Output:</strong> access token, token type, expiry in seconds, a flag stating whether two-factor verification is required, and a refresh token delivered as an HTTP-only cookie. When two-factor verification is required, a two-factor challenge token is returned instead of the access token and the refresh token.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-05:</strong> Anti-enumeration — when no account matches the identifier, or the password does not match, or the account has no password (created through Google only), the same answer is returned: 401 INVALID_CREDENTIALS. The answer never reveals whether the email address or the phone number exists.</li><li><strong>BR-06:</strong> Suspended / inactive account → 403 ACCOUNT_SUSPENDED, checked before password comparison. A status of DEACTIVATED → 403 ACCOUNT_DEACTIVATED.</li><li><strong>BR-07:</strong> Login accepts an identifier field auto-detected as email (contains &quot;@&quot;) or phone (E.164); the email part is matched case-insensitively, the phone part is normalized before lookup.</li><li><strong>BR-08:</strong> Access token is JWT RS256 with a 15-minute TTL; refresh token is an HttpOnly cookie only, 30-day TTL, never in the JSON body. When two-factor authentication is enabled no access token and no refresh token are issued at this step; a two-factor challenge token is returned instead and the refresh cookie is not set.</li><li><strong>BR-12:</strong> Refresh token <code>jti</code> is checked against a blacklist; a token issued before the most recent password change is rejected. A refresh is accepted only from the HTTP-only cookie, never from the request body. A missing cookie or an unusable/stale token → 401 REFRESH_TOKEN_INVALID. A blacklisted token → 401 REFRESH_TOKEN_BLACKLISTED. A successful refresh rotates the refresh token.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>identifier empty → Display: MSG02</li><li>password empty → Display: MSG02</li><li>identifier neither a valid email format nor a valid phone number → Display: MSG04</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The Guest opens /login and enters the identifier and the password.</li><li>The system resolves the identifier to an account and checks that the account status allows sign-in.</li><li>The system compares the submitted password with the stored password hash.</li><li>With two-factor authentication disabled the system records the sign-in, resolves the active workspace and issues an access token and a refresh token.</li><li>The system returns the tokens and sets the refresh token cookie.</li><li>The screen stores the access token, loads the profile and navigates to the Dashboard / Agency list; toast MSG11.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: Unknown identifier, wrong password, or an account without a password (BR-05) → 401 INVALID_CREDENTIALS, toast MSG07; the identifier is never confirmed to exist. 2.a2: The Guest re-enters the credentials or uses &quot;Forgot password&quot; (3.2.4).</li><li>2.b1: The account status is anything other than ACTIVE or DEACTIVATED (BR-06) → 403 ACCOUNT_SUSPENDED, toast MSG09. 2.b2: The Guest contacts support to resolve the account status.</li><li>2.c1: The account status is DEACTIVATED (BR-06) → 403 ACCOUNT_DEACTIVATED, toast MSG09. 2.c2: The Guest reactivates the account (3.2.9) or contacts support.</li><li>4.a1: Two-factor authentication is enabled on the account (BR-08) → no access token and no refresh token are issued; a two-factor challenge token is returned instead. 4.a2: The screen continues on the two-factor code screen (3.2.7) for the Guest to complete sign-in.</li><li>5.a1: Refresh requested without the cookie, or with an unusable or stale token (BR-12) → 401 REFRESH_TOKEN_INVALID, toast MSG22. 5.a2: Refresh requested with a token invalidated by sign-out (BR-12) → 401 REFRESH_TOKEN_BLACKLISTED, toast MSG22; either way the screen redirects the Guest back to /login.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The sign-in is recorded and the last sign-in time is updated.</li><li>An access token and a refresh token cookie are issued when two-factor authentication is disabled.</li><li>A two-factor challenge token, and no tokens, is issued when two-factor authentication is enabled.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Verifying the two-factor code and completing sign-in after the challenge — see FR 3.2.7 Two-Factor Verify.</li><li>Ending a session / clearing the refresh cookie — see FR 3.2.8 Logout.</li><li>Google OAuth sign-in — see FR 3.2.3.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../../../brandhub-business-service/src/main/java/com/brandhub/business/controller/AuthController.java.html">AuthController.java</a>, <a href="./../../../../../brandhub-business-service/src/main/java/com/brandhub/business/service/impl/AuthServiceImpl.java.html">AuthServiceImpl.java</a>, Section5_Requirement_Appendix.md (BR-05, BR-06, BR-07, BR-08, BR-12; MSG02, MSG04, MSG07, MSG09, MSG11, MSG22)</p><h2 id="dev-quick-login-repair-—-2026-10-04" tabindex="-1">Dev Quick Login repair — 2026-10-04 <a class="header-anchor" href="#dev-quick-login-repair-—-2026-10-04" aria-label="Permalink to &quot;Dev Quick Login repair — 2026-10-04&quot;">​</a></h2><p>Chỉ áp dụng helper <code>import.meta.env.DEV</code>. Nguyên nhân thực tế: DB có Admin/demo statistics nhưng thiếu <a href="mailto:user177@hotmail.com" target="_blank" rel="noreferrer">user177@hotmail.com</a>, <a href="mailto:user1@gmail.com" target="_blank" rel="noreferrer">user1@gmail.com</a>, <a href="mailto:user59@gmail.com" target="_blank" rel="noreferrer">user59@gmail.com</a> và không có Workspace/ClientProfile; bulk seeder bỏ qua vì marker Admin đã tồn tại.</p><ul><li>Giữ login và quyền thật từ API. Owner/Manager/Creator/Client là quyền Agency/Workspace, systemRole vẫn USER. Không bỏ AuthGuard/RequireRole hoặc mô phỏng role.</li><li>Bổ sung seed nhỏ, opt-in, transaction: chỉ tạo các tài khoản dev còn thiếu, Agency và hai Workspace thử nghiệm. User1 là MANAGER ở Workspace thứ nhất, CREATOR ở Workspace thứ hai; Client59 gắn qua ClientProfile. Không xóa dữ liệu, reset mật khẩu/status/quyền của tài khoản đã tồn tại.</li><li>Manager/Creator lấy <code>GET /api/v1/workspaces</code>, chọn <code>myRole</code> đúng nút; không dùng UUID cố định. Không có Workspace đúng quyền → tới danh sách Agency và báo hướng dẫn seed. Owner tới Agency, Client tới ClientProfile.</li><li>Helper xử lý challenge 2FA giống form thường, không gọi profile khi chưa có access token. Chuỗi lỗi VI/EN, loading khóa nút lặp.</li><li>Các package APPROVED trong seed là dữ liệu fixture riêng, không đổi trạng thái package thực tế.</li></ul>',30)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
